window.BANCO = window.BANCO || {};
window.BANCO.geografia = [
{n:"f",t:"Trabalho no Brasil",q:"O que é trabalho?",a:["Uma atividade que produz bens ou serviços","Apenas brincar com os amigos","Somente dormir e descansar","Apenas assistir televisão"],c:0,e:"Trabalho é toda atividade em que a pessoa produz algo: um bem (como um pão) ou um serviço (como dar aula). É assim que as coisas que usamos todos os dias são feitas!"},
{n:"f",t:"Trabalho no Brasil",q:"O que é trabalho remunerado?",a:["Trabalho feito só por diversão","Trabalho em que a pessoa recebe pagamento","Trabalho feito apenas em casa","Trabalho que ninguém precisa fazer"],c:1,e:"Remunerado quer dizer que a pessoa recebe dinheiro (salário) pelo que faz. É como a professora, que recebe pagamento por dar aulas."},
{n:"f",t:"Trabalho no Brasil",q:"Qual destas atividades é um exemplo de trabalho NÃO remunerado?",a:["Motorista de ônibus no seu horário de serviço","Médica atendendo no hospital onde é contratada","Trabalho voluntário em um abrigo de animais","Caixa de supermercado durante o expediente"],c:2,e:"O voluntário não recebe dinheiro: ele trabalha para ajudar. Já o motorista, a médica e o caixa recebem salário pelo que fazem."},
{n:"f",t:"Trabalho no Brasil",q:"Cuidar da casa, cozinhar e lavar roupa para a família é chamado de:",a:["Trabalho industrial","Trabalho agrícola","Trabalho de mineração","Trabalho doméstico"],c:3,e:"Trabalho doméstico é o trabalho feito dentro de casa, como cozinhar e limpar. Mesmo sem pagamento, é um trabalho muito importante para a família! 🏠"},
{n:"f",t:"Trabalho no Brasil",q:"O que são bens, na economia?",a:["Produtos que podemos tocar, como pão e roupa","Apenas sentimentos bons","Somente dinheiro guardado no banco","Apenas ideias que ninguém usa"],c:0,e:"Bens são coisas materiais, que dá para pegar: um tênis, um caderno, uma bicicleta. Já os serviços são atividades, como uma consulta médica."},
{n:"f",t:"Trabalho no Brasil",q:"O que é um serviço?",a:["Um objeto vendido na loja","Uma atividade feita para atender as pessoas, como dar aula","Uma fruta colhida no pomar","Um mineral retirado do solo"],c:1,e:"Serviço é uma atividade que ajuda as pessoas: o corte de cabelo, a aula, a consulta no dentista. Não é um objeto, é algo que alguém faz para você."},
{n:"f",t:"Tipos de trabalho",q:"O que caracteriza o trabalho formal?",a:["Não ter nenhum direito garantido","Trabalhar sem receber nada","Ter carteira de trabalho assinada e direitos garantidos","Trabalhar apenas aos domingos"],c:2,e:"No trabalho formal, a carteira assinada garante direitos como férias, 13º salário e aposentadoria. É como um combinado registrado no papel, que protege o trabalhador."},
{n:"f",t:"Tipos de trabalho",q:"O trabalhador informal é aquele que:",a:["Tem todos os direitos garantidos por lei","Trabalha sem carteira assinada e sem garantias","Recebe férias pagas todo ano","Sempre trabalha em grandes empresas"],c:1,e:"O trabalhador informal não tem carteira assinada, então fica sem garantias como férias pagas e 13º salário. Um exemplo é o vendedor ambulante."},
{n:"f",t:"Tipos de trabalho",q:"Qual destes é um direito do trabalhador com carteira assinada?",a:["Férias remuneradas","Trabalhar sem descanso","Não receber salário","Ser proibido de se aposentar"],c:0,e:"Quem tem carteira assinada tem direito a férias remuneradas: um período de descanso por ano, recebendo salário. Também tem 13º salário e aposentadoria."},
{n:"f",t:"Tipos de trabalho",q:"O que é o 13º salário?",a:["Um desconto no salário do trabalhador","Um imposto que o trabalhador paga","Uma multa por faltar ao trabalho","Um pagamento extra que o trabalhador formal recebe no fim do ano"],c:3,e:"O 13º é como um salário a mais, pago no fim do ano para quem tem carteira assinada. É um dos direitos do trabalho formal."},
{n:"f",t:"Tipos de trabalho",q:"O trabalhador autônomo é aquele que:",a:["Trabalha por conta própria, sem patrão","É sempre funcionário de uma fábrica","Só trabalha para o governo","Nunca recebe dinheiro pelo trabalho"],c:0,e:"Autônomo é quem trabalha por conta própria e organiza o próprio serviço, como um eletricista que atende vários clientes. Ele é o chefe de si mesmo!"},
{n:"f",t:"Tipos de trabalho",q:"O trabalho voluntário é aquele em que a pessoa:",a:["Recebe um salário muito alto","Trabalha para ajudar, sem receber pagamento","É obrigada a trabalhar pela lei","Só trabalha se ganhar presentes"],c:1,e:"O voluntário doa seu tempo para ajudar os outros, sem cobrar nada. Quem ensina crianças de graça em um projeto social é um exemplo."},
{n:"f",t:"Trabalho infantil",q:"No Brasil, o trabalho é proibido para menores de:",a:["10 anos","18 anos em qualquer situação","14 anos","8 anos"],c:2,e:"A lei brasileira proíbe o trabalho para menores de 14 anos. Dos 14 aos 16, o jovem só pode trabalhar como aprendiz, uma forma protegida de aprender uma profissão."},
{n:"f",t:"Trabalho infantil",q:"Entre 14 e 16 anos, o jovem brasileiro só pode trabalhar:",a:["Como aprendiz","Em qualquer emprego noturno","Em minas e pedreiras","Dirigindo caminhões"],c:0,e:"Nessa idade, a lei só permite o trabalho como aprendiz: o jovem aprende uma profissão com horários que não atrapalham a escola."},
{n:"f",t:"Trabalho infantil",q:"Qual lei protege os direitos das crianças e adolescentes no Brasil?",a:["O Código de Trânsito","O ECA — Estatuto da Criança e do Adolescente","A Lei do Inquilinato","O Código Florestal"],c:1,e:"O ECA é a lei que garante os direitos de crianças e adolescentes, como estudar, brincar e ser protegido. É como um escudo de leis para a infância!"},
{n:"f",t:"Trabalho infantil",q:"Segundo o ECA, toda criança tem direito a:",a:["Trabalhar em fábricas","Sustentar a família sozinha","Ficar sem ir à escola","Estudar e brincar"],c:3,e:"Estudar e brincar são direitos de toda criança! O ECA garante isso porque a infância é o tempo de aprender e crescer com saúde."},
{n:"f",t:"Trabalho infantil",q:"Por que o trabalho infantil é um problema?",a:["Porque criança ganha salário muito alto","Porque atrapalha os estudos, a saúde e a infância","Porque criança trabalha rápido demais","Porque as fábricas ficam muito cheias"],c:1,e:"Quando a criança trabalha, ela perde tempo de estudar, brincar e descansar, e ainda pode se machucar. Por isso o trabalho infantil é proibido."},
{n:"f",t:"Trabalho infantil",q:"O lugar da criança de 10 anos, segundo a lei brasileira, é:",a:["Na lavoura, colhendo o dia todo","Na fábrica, operando máquinas","Na escola, estudando e brincando","Na rua, vendendo doces"],c:2,e:"Com 10 anos, o lugar da criança é na escola e nos momentos de brincadeira. Trabalhar só é permitido a partir dos 14 anos, e mesmo assim como aprendiz."},
{n:"f",t:"Tecnologia e trabalho",q:"O que aconteceu com o trabalho por causa das máquinas e computadores?",a:["O jeito de trabalhar mudou em muitas profissões","Nada mudou no trabalho","Todas as pessoas pararam de trabalhar","O trabalho ficou igual ao de 200 anos atrás"],c:0,e:"A tecnologia mudou o jeito de trabalhar: muitas tarefas que eram feitas à mão agora são feitas com máquinas e computadores, de forma mais rápida."},
{n:"f",t:"Tecnologia e trabalho",q:"O que é automação?",a:["Fazer tudo sem nenhuma ferramenta","Trabalhar apenas à noite","Proibir o uso de computadores","O uso de máquinas para fazer tarefas que antes eram feitas por pessoas"],c:3,e:"Automação é quando máquinas e robôs passam a fazer tarefas sozinhos, como um robô que monta carros na fábrica. As pessoas passam a comandar e cuidar das máquinas."},
{n:"f",t:"Tecnologia e trabalho",q:"O que é home office (trabalho remoto)?",a:["Trabalhar dentro de um escritório da empresa todos os dias","Trabalhar de casa, usando computador e internet","Trabalhar apenas ao ar livre","Trabalhar sem usar nenhuma tecnologia"],c:1,e:"Home office é trabalhar de casa, conectado pela internet. A pessoa participa de reuniões e envia tarefas pelo computador, sem precisar ir até a empresa."},
{n:"f",t:"Tecnologia e trabalho",q:"Com o avanço da tecnologia, algumas profissões desaparecem e outras:",a:["Também desaparecem todas","Ficam proibidas","Surgem, como as ligadas à tecnologia","Viram brincadeiras"],c:2,e:"É como uma troca: o acendedor de lampiões sumiu, mas surgiram profissões novas, como programador de computadores e técnico de robôs."},
{n:"f",t:"Tecnologia e trabalho",q:"Qual máquina ajuda na colheita de grãos nas fazendas modernas?",a:["A colheitadeira","A batedeira de bolo","O liquidificador","A máquina de lavar roupa"],c:0,e:"A colheitadeira é uma máquina enorme que colhe os grãos rapidinho, fazendo o trabalho que antes precisava de muitas pessoas com ferramentas manuais."},
{n:"f",t:"Tecnologia e trabalho",q:"Para conseguir os novos empregos ligados à tecnologia, as pessoas precisam:",a:["Parar de estudar","Evitar computadores","Trabalhar sem aprender nada novo","Estudar e se qualificar"],c:3,e:"As profissões novas pedem conhecimento! Por isso é importante estudar sempre e aprender coisas novas, como usar bem os computadores."},
{n:"f",t:"Setores da economia",q:"Quantos são os setores da economia?",a:["Dez","Três","Sete","Apenas um"],c:1,e:"A economia se divide em três setores: primário (natureza), secundário (indústria) e terciário (comércio e serviços). Cada um tem seu papel!"},
{n:"f",t:"Setores da economia",q:"O setor primário é aquele que:",a:["Vende produtos em lojas","Transforma matéria-prima em produtos","Retira produtos da natureza","Oferece serviços como aulas e consultas"],c:2,e:"O setor primário retira da natureza o que precisamos: alimentos da agricultura, animais da pecuária, peixes da pesca e minérios do solo."},
{n:"f",t:"Setores da economia",q:"O setor secundário é aquele que:",a:["Transforma matéria-prima em produtos, como nas fábricas","Planta e colhe alimentos","Pesca peixes no mar","Corta cabelo e dá aulas"],c:0,e:"O setor secundário transforma! A fábrica pega o algodão (matéria-prima) e o transforma em camiseta. As indústrias e a construção civil fazem parte dele."},
{n:"f",t:"Setores da economia",q:"O setor terciário é formado por:",a:["Minas de ouro e ferro","Plantações de soja","Fábricas de automóveis","Comércio e serviços, como lojas e escolas"],c:3,e:"O setor terciário reúne o comércio (lojas, mercados) e os serviços (escolas, hospitais, transporte). É o setor que mais emprega pessoas no Brasil!"},
{n:"f",t:"Setores da economia",q:"A agricultura e a pecuária fazem parte de qual setor?",a:["Setor terciário","Setor secundário","Setor de serviços","Setor primário"],c:3,e:"Plantar e criar animais são atividades que retiram produtos da natureza, por isso pertencem ao setor primário."},
{n:"f",t:"Setores da economia",q:"Qual setor da economia mais emprega pessoas no Brasil?",a:["O setor terciário, de comércio e serviços","O setor primário","O setor secundário","Nenhum setor emprega pessoas"],c:0,e:"O setor terciário é o campeão de empregos no Brasil! Pense em quantas pessoas trabalham em lojas, escolas, hospitais, bancos e transportes."},
{n:"f",t:"Energia",q:"Para que serve a energia?",a:["Apenas para enfeitar as casas","Para mover fábricas, máquinas, transportes e iluminar casas","Somente para carregar celular","Para nada importante"],c:1,e:"A energia move o mundo do trabalho: liga as máquinas das fábricas, os meios de transporte e ilumina nossas casas. Sem ela, quase tudo para!"},
{n:"f",t:"Energia",q:"Qual é a principal fonte de energia elétrica do Brasil?",a:["Energia de pilhas","Energia das termelétricas a carvão","Energia hidrelétrica, que usa a força da água","Energia de lenha"],c:2,e:"O Brasil tem muitos rios, então a maior parte da nossa energia vem das usinas hidrelétricas, que usam a força da água para gerar eletricidade. 💧"},
{n:"f",t:"Energia",q:"A energia eólica é gerada a partir:",a:["Do vento","Do petróleo","Do carvão mineral","Do lixo"],c:0,e:"Eólica vem de Éolo, o senhor dos ventos na mitologia! Grandes cata-ventos, chamados aerogeradores, transformam a força do vento em eletricidade."},
{n:"f",t:"Energia",q:"A energia solar é obtida a partir:",a:["Da queima de gasolina","Da força dos rios","Do gás natural","Da luz do Sol"],c:3,e:"A energia solar vem da luz do Sol, captada por placas especiais chamadas painéis solares. É uma energia limpa e renovável!"},
{n:"f",t:"Energia",q:"O que a usina termelétrica faz para gerar energia?",a:["Usa apenas a luz da Lua","Queima combustíveis, o que polui mais o ar","Usa a força das ondas do mar somente","Planta árvores"],c:1,e:"A termelétrica queima combustíveis (como carvão, óleo ou gás) para gerar eletricidade. Essa queima solta fumaça, por isso ela polui mais que outras fontes."},
{n:"f",t:"Trabalho no Brasil",q:"Qual destas atividades é um serviço, e não um bem?",a:["Um sapato","Uma bicicleta","Uma consulta no dentista","Um pacote de arroz"],c:2,e:"A consulta é uma atividade que o dentista faz para cuidar de você: isso é um serviço. Sapato, bicicleta e arroz são bens, coisas que podemos tocar e guardar."},
{n:"f",t:"Trabalho no Brasil",q:"Quem trabalha produz bens ou serviços que servem para:",a:["Serem jogados fora sem uso","Atender as necessidades das pessoas","Ficarem escondidos para sempre","Enfeitar as fábricas apenas"],c:1,e:"Todo trabalho existe para atender necessidades: o padeiro faz o pão que comemos, a médica cuida da nossa saúde. Um ajuda o outro!"},
{n:"f",t:"Trabalho no Brasil",q:"O salário é:",a:["Um presente de aniversário","Uma multa paga pelo trabalhador","Um imposto do governo","O pagamento que o trabalhador recebe pelo seu trabalho"],c:3,e:"Salário é o dinheiro que a pessoa recebe em troca do trabalho que fez. Com ele, o trabalhador compra comida, roupas e paga as contas."},
{n:"f",t:"Trabalho no Brasil",q:"A aposentadoria é o direito de:",a:["Descansar recebendo pagamento depois de muitos anos de trabalho","Trabalhar para sempre sem parar","Nunca receber dinheiro","Começar a trabalhar aos 5 anos"],c:0,e:"Depois de trabalhar por muitos anos, a pessoa se aposenta: para de trabalhar e continua recebendo um dinheiro todo mês para viver com tranquilidade."},
{n:"f",t:"Trabalho no Brasil",q:"Quem ajuda em uma campanha de doação de alimentos sem receber nada faz trabalho:",a:["Formal","Industrial","Voluntário","Mineral"],c:2,e:"Trabalho voluntário é feito de coração, sem pagamento, para ajudar quem precisa. A recompensa é fazer o bem! ❤️"},
{n:"f",t:"Trabalho no Brasil",q:"O trabalho doméstico feito pela própria família em casa é:",a:["Um trabalho não remunerado","Pago com salário todo mês","Um trabalho do setor industrial","Proibido por lei"],c:0,e:"Quando alguém da família cozinha e arruma a própria casa, não recebe salário por isso: é trabalho não remunerado, mas muito valioso para todos."},
{n:"f",t:"Tipos de trabalho",q:"O documento que registra o emprego formal do trabalhador brasileiro é:",a:["O passaporte","A certidão de nascimento","O título de eleitor","A carteira de trabalho"],c:3,e:"A carteira de trabalho é o documento onde o emprego fica registrado (assinado). É ela que garante os direitos do trabalhador formal."},
{n:"f",t:"Tipos de trabalho",q:"Um vendedor ambulante que vende doces na rua, sem carteira assinada, é exemplo de trabalho:",a:["Formal","Informal","Voluntário","Escolar"],c:1,e:"Sem carteira assinada, o vendedor ambulante está na informalidade: ele ganha dinheiro, mas não tem garantias como férias pagas e 13º salário."},
{n:"f",t:"Tipos de trabalho",q:"Qual trabalhador tem direito garantido a férias remuneradas e 13º salário?",a:["O que tem carteira de trabalho assinada","O que trabalha sem nenhum registro","O voluntário","Qualquer pessoa, mesmo sem trabalhar"],c:0,e:"Esses direitos são do trabalhador formal, com carteira assinada. O informal e o voluntário não têm essas garantias por lei."},
{n:"f",t:"Tipos de trabalho",q:"Uma cabeleireira que atende em casa, marca os próprios horários e não tem patrão é:",a:["Funcionária pública","Trabalhadora escrava","Autônoma","Aposentada"],c:2,e:"Ela trabalha por conta própria: decide horários, preços e clientes. Isso é ser autônoma, a chefe de si mesma!"},
{n:"f",t:"Tipos de trabalho",q:"Qual é uma desvantagem do trabalho informal?",a:["Receber férias em dobro","Ter salário garantido por lei","Ter muitos direitos garantidos","Não ter garantias como férias e aposentadoria"],c:3,e:"O trabalhador informal fica desprotegido: se adoecer ou envelhecer, não tem as garantias que a carteira assinada dá, como férias pagas e aposentadoria."},
{n:"f",t:"Tipos de trabalho",q:"Trabalhar como aprendiz significa:",a:["Trabalhar aprendendo uma profissão, com estudo garantido","Trabalhar a noite inteira","Parar de estudar para trabalhar","Trabalhar sem aprender nada"],c:0,e:"O aprendiz aprende uma profissão na prática, mas com proteção: horários curtos e a escola sempre em primeiro lugar."},
{n:"f",t:"Trabalho infantil",q:"Trabalho infantil é quando:",a:["Adultos trabalham em fábricas de brinquedos","Crianças brincam de faz de conta de profissões","Crianças menores de 14 anos trabalham de verdade","Jovens de 20 anos começam um emprego"],c:2,e:"Trabalho infantil é criança trabalhando de verdade, o que é proibido no Brasil para menores de 14 anos. Brincar de ser veterinária, claro, pode à vontade!"},
{n:"f",t:"Trabalho infantil",q:"O que o trabalho infantil pode prejudicar na vida de uma criança?",a:["Os estudos, a saúde e as brincadeiras","Apenas o time de futebol favorito","Nada, pois criança não se cansa","Somente os desenhos animados"],c:0,e:"Criança que trabalha perde aulas, fica cansada e sem tempo de brincar. Isso prejudica o corpo, a mente e o futuro dela."},
{n:"f",t:"Trabalho infantil",q:"A sigla ECA significa:",a:["Escola de Crianças Atletas","Estatuto da Criança e do Adolescente","Empresa de Comércio e Agricultura","Energia, Ciência e Arte"],c:1,e:"ECA quer dizer Estatuto da Criança e do Adolescente, a lei brasileira que protege os direitos de quem ainda está crescendo."},
{n:"f",t:"Trabalho infantil",q:"Se uma criança de 9 anos é vista trabalhando o dia todo, isso é:",a:["Normal e permitido","Um direito da criança","Uma obrigação da escola","Proibido por lei no Brasil"],c:3,e:"Com 9 anos, trabalhar é proibido! A lei diz que o lugar dela é na escola e brincando. Denúncias podem ser feitas para proteger essa criança."},
{n:"f",t:"Trabalho infantil",q:"Além de estudar, o ECA garante que toda criança tem direito de:",a:["Dirigir automóveis","Trabalhar em obras","Brincar e descansar","Votar nas eleições"],c:2,e:"Brincar não é perda de tempo: é um direito! Brincando, a criança aprende, faz amigos e cresce feliz e saudável."},
{n:"f",t:"Tecnologia e trabalho",q:"Antigamente, muitas tarefas eram feitas à mão. Hoje, muitas delas são feitas:",a:["Por máquinas e computadores","Apenas por animais","Por ninguém","Somente por crianças"],c:0,e:"A tecnologia trouxe máquinas e computadores que fazem tarefas com rapidez. As pessoas passaram a operar e cuidar dessas máquinas."},
{n:"f",t:"Tecnologia e trabalho",q:"Qual destas é uma profissão nova, que surgiu com a tecnologia?",a:["Acendedor de lampião","Desenvolvedor de aplicativos","Cocheiro de carruagem","Telefonista de central manual"],c:1,e:"Desenvolvedor de aplicativos é uma profissão que só existe por causa dos celulares e computadores. As outras três foram desaparecendo com o tempo."},
{n:"f",t:"Tecnologia e trabalho",q:"No campo, a tecnologia aparece em máquinas como:",a:["Videogames de corrida","Máquinas de sorvete","Tratores e colheitadeiras","Aspiradores de pó"],c:2,e:"Tratores e colheitadeiras são a tecnologia do campo: preparam a terra e colhem os alimentos com muito mais rapidez que o trabalho manual."},
{n:"f",t:"Tecnologia e trabalho",q:"Quem trabalha em home office precisa principalmente de:",a:["Um trator","Computador e internet","Uma colheitadeira","Um forno industrial"],c:1,e:"Para trabalhar de casa, a pessoa usa computador e internet: assim participa de reuniões e envia seu trabalho sem sair de casa."},
{n:"f",t:"Tecnologia e trabalho",q:"Robôs que montam carros nas fábricas são um exemplo de:",a:["Trabalho voluntário","Extrativismo","Agricultura familiar","Automação na indústria"],c:3,e:"Quando robôs fazem tarefas da linha de montagem, chamamos de automação. As pessoas programam e supervisionam esses robôs."},
{n:"f",t:"Setores da economia",q:"A pesca faz parte de qual setor da economia?",a:["Primário","Secundário","Terciário","Nenhum setor"],c:0,e:"O pescador retira o peixe da natureza (do mar ou do rio), por isso a pesca é do setor primário."},
{n:"f",t:"Setores da economia",q:"As fábricas e indústrias fazem parte do setor:",a:["Primário","Secundário","Terciário","Quaternário"],c:1,e:"As fábricas transformam matérias-primas em produtos: é a marca do setor secundário. Farinha vira pão, tecido vira roupa!"},
{n:"f",t:"Setores da economia",q:"Lojas, escolas, hospitais e bancos fazem parte do setor:",a:["Primário","Secundário","Terciário","Mineral"],c:2,e:"Todos esses lugares vendem produtos ou oferecem serviços às pessoas, por isso pertencem ao setor terciário."},
{n:"f",t:"Setores da economia",q:"O que é matéria-prima?",a:["Um produto pronto para usar","Uma loja de materiais","O material da natureza usado para fabricar produtos","Um tipo de serviço bancário"],c:2,e:"Matéria-prima é o ingrediente que vem da natureza e vira produto na fábrica: o algodão da camiseta, o trigo do pão, o minério do ferro."},
{n:"f",t:"Setores da economia",q:"Retirar madeira, látex ou minérios da natureza chama-se:",a:["Comércio","Turismo","Construção civil","Extrativismo"],c:3,e:"Extrativismo é extrair (retirar) riquezas da natureza, como madeira, frutos, látex e minérios. É uma atividade do setor primário."},
{n:"f",t:"Setores da economia",q:"A construção civil, que ergue casas e prédios, pertence ao setor:",a:["Primário","Secundário","Terciário","De pesca"],c:1,e:"A construção civil transforma materiais (cimento, tijolo, areia) em casas e prédios. Por transformar, faz parte do setor secundário."},
{n:"f",t:"Energia",q:"Uma fonte de energia renovável é aquela que:",a:["Acaba para sempre depois de usada","Vem apenas do petróleo","Não se esgota, pois a natureza a renova","Polui mais que todas as outras"],c:2,e:"Renovável é a fonte que a natureza repõe sempre: o Sol nasce todo dia, o vento volta a soprar, a chuva enche os rios."},
{n:"f",t:"Energia",q:"Qual destas é uma fonte de energia NÃO renovável?",a:["Petróleo","Vento","Sol","Força da água dos rios"],c:0,e:"O petróleo demorou milhões de anos para se formar debaixo da terra: se usarmos tudo, acabou! Já sol, vento e água a natureza renova sempre."},
{n:"f",t:"Energia",q:"A energia de biomassa pode ser produzida a partir:",a:["De pedras preciosas","Do bagaço da cana-de-açúcar","Do vidro reciclado","Do plástico novo"],c:1,e:"Biomassa é energia que vem de plantas e restos vegetais, como o bagaço da cana. O que seria lixo vira energia!"},
{n:"f",t:"Energia",q:"Qual fonte de energia usa a força da água armazenada em represas?",a:["Solar","Eólica","Termelétrica a carvão","Hidrelétrica"],c:3,e:"Hidro vem de água! Nas hidrelétricas, a água da represa desce com força, gira as turbinas e gera eletricidade."},
{n:"f",t:"Energia",q:"Qual destas atitudes ajuda a economizar energia?",a:["Deixar todas as luzes acesas o dia todo","Dormir com a televisão ligada","Apagar a luz ao sair do quarto","Abrir a geladeira e ficar olhando"],c:2,e:"Apagar a luz que não está sendo usada evita desperdício. Economizar energia ajuda o planeta e o bolso da família!"},
{n:"f",t:"Energia",q:"Carvão mineral, petróleo e gás natural são fontes:",a:["Renováveis","Não renováveis","Infinitas","Que vêm do vento"],c:1,e:"Essas fontes vieram de restos de seres vivos que ficaram milhões de anos sob a terra. Elas podem acabar, por isso são não renováveis."},
{n:"f",t:"Energia",q:"Os grandes cata-ventos brancos que geram eletricidade chamam-se:",a:["Aerogeradores","Painéis solares","Turbinas de avião","Ventiladores de teto"],c:0,e:"Os aerogeradores são os gigantes cata-ventos dos parques eólicos: o vento gira as hélices e vira eletricidade."},
{n:"m",t:"Trabalho no Brasil",q:"Dona Célia arruma a casa, cozinha e cuida dos filhos todos os dias, e ninguém lhe paga por isso. Podemos dizer que ela:",a:["Não trabalha, porque não recebe dinheiro","Faz trabalho voluntário numa empresa","Faz um trabalho de verdade, mas não remunerado","Tem um emprego com carteira assinada"],c:2,e:"Trabalho não é só o que dá dinheiro. Cuidar da casa e da família é um trabalho de verdade, só que não remunerado. 💙"},
{n:"m",t:"Trabalho no Brasil",q:"Um mecânico conserta o carro de um cliente e cobra pelo conserto. Ele produziu:",a:["Um bem, porque o carro é um objeto","Um serviço, porque ele fez um trabalho para outra pessoa","Uma matéria-prima","Nada, pois o carro já existia"],c:1,e:"O mecânico não fabricou o carro: ele prestou um serviço, que é um trabalho feito para atender alguém. Fábrica faz bem; conserto é serviço."},
{n:"m",t:"Trabalho no Brasil",q:"Dona Maria assa bolos em casa e vende para os vizinhos. O bolo pronto é um exemplo de:",a:["Matéria-prima industrial","Serviço, porque ela atende os vizinhos","Trabalho voluntário","Bem, porque é um produto que se pode pegar e usar"],c:3,e:"Bem é o produto que você pega na mão, como o bolo. Serviço é o trabalho em si, como entregar ou fazer a festa."},
{n:"m",t:"Trabalho no Brasil",q:"Qual destas situações NÃO é considerada trabalho?",a:["Uma pessoa assistindo a um filme deitada no sofá","Um pai lavando a louça da família","Uma enfermeira cuidando de pacientes","Um voluntário distribuindo sopa na praça"],c:0,e:"Assistir a um filme é descanso e lazer, não produz bem nem serviço para ninguém. Já lavar a louça e ser voluntário produzem serviços, mesmo sem pagamento."},
{n:"m",t:"Trabalho no Brasil",q:"Uma professora dá aula na escola de manhã e, à noite, cuida da própria casa. Sobre esses dois trabalhos:",a:["Só a aula é trabalho; cuidar da casa não é","Os dois são remunerados","Um é remunerado (a aula) e o outro não (a casa)","Nenhum dos dois é trabalho"],c:2,e:"Ela trabalha duas vezes: na escola recebe salário e em casa não recebe nada. Os dois são trabalho, mas só um é remunerado."},
{n:"m",t:"Trabalho no Brasil",q:"Por que o trabalho das pessoas é importante para toda a sociedade?",a:["Porque só serve para deixar as pessoas cansadas","Porque produz os bens e serviços que todos usam no dia a dia","Porque diminui o número de escolas","Porque impede que as cidades cresçam"],c:1,e:"O pão da manhã, o ônibus, o hospital: tudo isso existe porque alguém trabalhou. É o trabalho que faz a vida em sociedade funcionar."},
{n:"m",t:"Trabalho no Brasil",q:"Qual destes trabalhadores produz um SERVIÇO, e não um bem?",a:["O carpinteiro que monta uma mesa","O operário da fábrica de tênis","O agricultor que colhe milho","O motorista de ônibus escolar"],c:3,e:"O motorista transporta pessoas: não sai nenhum objeto novo das mãos dele, e isso é serviço. Os outros três produzem coisas que se pode pegar."},
{n:"m",t:"Trabalho no Brasil",q:"Um patrão que nunca deixa o funcionário tirar férias está:",a:["Sendo generoso com o funcionário","Ajudando o funcionário a ganhar mais","Cumprindo corretamente a lei","Desrespeitando um direito do trabalhador"],c:3,e:"Férias não são um favor: são um direito garantido por lei para o trabalhador descansar. Quem não deixa tirar está descumprindo a lei."},
{n:"m",t:"Trabalho no Brasil",q:"O descanso semanal remunerado significa que o trabalhador formal:",a:["Trabalha todos os dias sem parar","Perde o salário do dia em que descansa","Só descansa se sobrar tempo","Tem direito a um dia de descanso por semana e continua recebendo"],c:3,e:"Remunerado quer dizer que o dia de descanso é pago. Por isso o trabalhador pode folgar uma vez por semana sem ver o salário diminuir."},
{n:"m",t:"Trabalho no Brasil",q:"Seu Jorge trabalha num hospital público e recebe salário todo mês. O trabalho dele é:",a:["Não remunerado","Voluntário","Remunerado","Uma brincadeira"],c:2,e:"Receber salário todo mês é a marca do trabalho remunerado. Se ele fizesse o mesmo de graça, aí seria trabalho voluntário."},
{n:"m",t:"Trabalho no Brasil",q:"Um grupo de vizinhos limpa a praça do bairro num sábado, sem receber nada. Esse é um exemplo de:",a:["Trabalho remunerado","Trabalho voluntário","Trabalho infantil","Trabalho formal com carteira assinada"],c:1,e:"Quando a pessoa trabalha para ajudar a comunidade e não recebe pagamento, é trabalho voluntário. Ele melhora o lugar onde todos vivem."},
{n:"m",t:"Trabalho no Brasil",q:"O salário do trabalhador serve principalmente para:",a:["Substituir o estudo dos filhos","Enfeitar a carteira de trabalho","Pagar os impostos da empresa","Comprar os bens e serviços de que a família precisa"],c:3,e:"Com o salário a família compra comida, roupa, transporte e paga contas. É a troca: a pessoa oferece seu trabalho e recebe dinheiro para viver."},
{n:"m",t:"Tipos de trabalho",q:"Seu Antônio vende pipoca no seu carrinho na praça e não tem carteira assinada nem recolhe nada. O trabalho dele é:",a:["Formal, com todos os direitos garantidos","De aprendiz, por ser um carrinho pequeno","Voluntário, porque é na rua","Informal, sem carteira assinada e sem garantias"],c:3,e:"Sem carteira e sem registro, o trabalho é informal: ele ganha dinheiro, mas não tem férias, 13º nem garantia de aposentadoria."},
{n:"m",t:"Tipos de trabalho",q:"Ana foi contratada por um supermercado, assinou a carteira e recebe férias e 13º salário. O trabalho dela é:",a:["Informal","Voluntário","Proibido pela lei","Formal"],c:3,e:"Carteira assinada mais férias e 13º são a marca do trabalho formal. É o tipo de trabalho com mais direitos garantidos."},
{n:"m",t:"Tipos de trabalho",q:"Bruno passa os domingos ajudando num abrigo de animais e não recebe nenhum pagamento. Ele faz trabalho:",a:["Voluntário","Informal","Autônomo","Formal"],c:0,e:"Quem trabalha de graça para ajudar uma causa faz trabalho voluntário. O pagamento é a alegria de ajudar quem precisa. 🐶"},
{n:"m",t:"Tipos de trabalho",q:"Um eletricista atende chamados de várias casas, marca seus próprios horários, combina o preço e não tem patrão. Ele é:",a:["Empregado formal","Voluntário","Aprendiz","Trabalhador autônomo"],c:3,e:"Autônomo é quem trabalha por conta própria, sem patrão, decidindo horários e preços. Ele é o dono do próprio trabalho."},
{n:"m",t:"Tipos de trabalho",q:"Qual destes trabalhadores tem direito garantido ao 13º salário?",a:["O jardineiro que trabalha por conta própria sem registro","O ambulante que vende água no semáforo","A pessoa que faz trabalho voluntário","O vendedor com carteira assinada na loja"],c:3,e:"O 13º salário é um direito de quem tem carteira assinada. Quem trabalha informalmente não recebe esse pagamento extra no fim do ano."},
{n:"m",t:"Tipos de trabalho",q:"Uma manicure aluga uma cadeira no salão, escolhe seus horários, atende suas clientes e não tem patrão. Ela é:",a:["Empregada formal do salão","Autônoma","Aprendiz do salão","Voluntária"],c:1,e:"Ela usa o espaço do salão, mas o trabalho é dela: escolhe horários e clientes. Isso é trabalho autônomo, por conta própria."},
{n:"m",t:"Tipos de trabalho",q:"Dois pintores fazem o mesmo serviço: um tem carteira assinada, o outro não. Quem tem mais direitos garantidos?",a:["O que tem carteira assinada","O que não tem carteira, porque ganha mais por dia","Os dois têm exatamente os mesmos direitos","Nenhum dos dois tem direitos"],c:0,e:"O trabalho pode ser igual, mas os direitos não. Com carteira assinada vêm férias, 13º e contribuição para a aposentadoria."},
{n:"m",t:"Tipos de trabalho",q:"Seu Rui trabalhou oito anos sem carteira assinada. Isso pode dificultar a aposentadoria dele porque:",a:["Ele trabalhou pouco tempo para se aposentar","Nesses anos não houve contribuição registrada em nome dele","A aposentadoria existe apenas para trabalhadores autônomos","Ele deveria ter trabalhado no período da noite"],c:1,e:"A aposentadoria vai sendo construída pelas contribuições de cada ano trabalhado. Sem registro, esse tempo todo não fica guardado no nome do trabalhador."},
{n:"m",t:"Tipos de trabalho",q:"Um jovem de 15 anos assinou contrato de Jovem Aprendiz numa empresa e continua estudando. Isso é:",a:["Proibido, porque ele tem menos de 18 anos","Proibido, porque aprendiz não existe no Brasil","Permitido, pois entre 14 e 16 anos só se pode trabalhar como aprendiz","Permitido só se ele parar de estudar"],c:2,e:"A lei permite o trabalho aos 14 e 15 anos apenas na condição de aprendiz, com jornada menor e escola em primeiro lugar."},
{n:"m",t:"Tipos de trabalho",q:"O que a pessoa que faz trabalho voluntário recebe pelo seu esforço?",a:["Nenhum pagamento em dinheiro","Um salário menor que o normal","Férias e 13º salário","Uma carteira de trabalho assinada"],c:0,e:"Voluntário não recebe dinheiro: a recompensa é ajudar as pessoas e a comunidade. Por isso não tem salário, férias nem 13º."},
{n:"m",t:"Tipos de trabalho",q:"Seu Pedro é motorista de uma empresa, tem carteira assinada e cumpre o horário combinado com o patrão. Ele é:",a:["Empregado formal","Voluntário","Autônomo","Trabalhador informal"],c:0,e:"Ter patrão, horário e carteira assinada é o retrato do empregado formal. O autônomo é justamente o contrário: não tem patrão."},
{n:"m",t:"Tipos de trabalho",q:"Por que muitas pessoas preferem conseguir um trabalho formal?",a:["Porque assim não precisam trabalhar todos os dias","Porque o trabalho formal não tem horário","Por causa da segurança dos direitos, como férias, 13º e aposentadoria","Porque no trabalho formal ninguém tem chefe"],c:2,e:"O trabalho formal traz previsibilidade: salário na data, descanso pago e proteção no futuro. É segurança para a família."},
{n:"m",t:"Trabalho infantil",q:"Um menino de 11 anos vende balas no semáforo em horário de aula. Sobre essa situação:",a:["É permitido, porque a rua é um lugar público","É trabalho infantil, proibido; o lugar dele é na escola","É trabalho autônomo, permitido pela lei","É trabalho voluntário"],c:1,e:"Criança de 11 anos não pode trabalhar no Brasil. O direito dela é estudar, brincar e ser cuidada pelos adultos. 💙"},
{n:"m",t:"Trabalho infantil",q:"Uma criança de 10 anos arruma o próprio quarto e leva o prato até a pia. Isso é:",a:["Trabalho infantil proibido pela lei","Trabalho remunerado","Trabalho informal","Colaboração em casa, adequada à idade dela"],c:3,e:"Tarefas leves, curtas e adequadas à idade ajudam a criança a aprender responsabilidade. Trabalho infantil é bem diferente: são horas de trabalho para gerar renda."},
{n:"m",t:"Trabalho infantil",q:"No Brasil, um adolescente de 17 anos pode trabalhar com carteira assinada, mas NÃO pode:",a:["Estudar ao mesmo tempo","Fazer trabalho noturno, perigoso ou insalubre","Receber salário","Ter férias"],c:1,e:"Dos 16 aos 18 o jovem pode ser contratado, mas a lei o protege de trabalho à noite ou que ofereça risco à saúde."},
{n:"m",t:"Trabalho infantil",q:"Segundo o ECA, qual é a principal ocupação de uma criança de 10 anos?",a:["Trabalhar meio período","Estudar, além de brincar e conviver com a família","Cuidar sozinha dos irmãos o dia todo","Vender produtos na rua"],c:1,e:"A lei é bem clara: a tarefa da criança é aprender. Estudar hoje é o que abre as portas para o trabalho de amanhã."},
{n:"m",t:"Trabalho infantil",q:"Se uma família passa por dificuldade financeira, colocar o filho de 12 anos para trabalhar:",a:["É a melhor solução, pois aumenta a renda","Continua proibido; existem programas públicos de apoio às famílias","É permitido se a mãe autorizar por escrito","É permitido nos fins de semana"],c:1,e:"Nem a autorização dos pais libera o trabalho infantil. O caminho certo é buscar apoio nos programas sociais e manter a criança na escola."},
{n:"m",t:"Trabalho infantil",q:"Por que o trabalho infantil atrapalha os estudos?",a:["Porque estudar e trabalhar são a mesma coisa","Porque a escola fecha quando o aluno trabalha","Porque a criança fica cansada, falta às aulas e não tem tempo de estudar","Porque os professores não gostam"],c:2,e:"Quem trabalha muitas horas chega exausto na aula e perde conteúdo. Com o tempo, muitos acabam abandonando a escola."},
{n:"m",t:"Trabalho infantil",q:"O que o ECA garante às crianças e adolescentes?",a:["Só o direito de trabalhar","Apenas o direito ao lazer","Direito à educação, à saúde, ao lazer e à proteção contra o trabalho infantil","O direito de escolher trabalhar aos 10 anos"],c:2,e:"O Estatuto da Criança e do Adolescente reúne vários direitos ao mesmo tempo: estudar, ter saúde, brincar e ser protegido."},
{n:"m",t:"Trabalho infantil",q:"Se alguém percebe uma criança trabalhando em vez de estudar, o certo é:",a:["Avisar um adulto de confiança ou o Conselho Tutelar","Comprar o produto dela para ajudar","Fingir que não viu","Contratá-la para outro serviço"],c:0,e:"O Conselho Tutelar existe para proteger crianças nessas situações. Avisar é ajudar de verdade, muito mais do que dar dinheiro."},
{n:"m",t:"Trabalho infantil",q:"Qual afirmação sobre a idade mínima de trabalho no Brasil está correta?",a:["Pode-se trabalhar em qualquer idade, se a família precisar","O trabalho é liberado a partir dos 12 anos","O trabalho é proibido para menores de 16 anos, permitido como aprendiz a partir dos 14","Só quem tem 21 anos pode trabalhar"],c:2,e:"A regra tem duas partes: aos 14 e 15 anos só como aprendiz, e o trabalho comum começa aos 16 anos."},
{n:"m",t:"Trabalho infantil",q:"Além de prejudicar os estudos, o trabalho infantil também pode prejudicar:",a:["A saúde e o tempo de brincar da criança","Apenas a nota de matemática","O salário dos adultos da rua","Nada, é totalmente seguro"],c:0,e:"O corpo da criança está crescendo, e esforço demais machuca. Brincar também é essencial para crescer bem e feliz."},
{n:"m",t:"Trabalho infantil",q:"Um adolescente de 15 anos que é aprendiz numa empresa deve:",a:["Abandonar a escola para render mais no trabalho","Trabalhar à noite para aprender mais","Continuar estudando, com jornada de trabalho reduzida","Fazer os serviços mais perigosos da empresa"],c:2,e:"Aprendiz é para aprender uma profissão sem abrir mão da escola. Por isso a jornada é curta e as tarefas perigosas são proibidas."},
{n:"m",t:"Tecnologia e trabalho",q:"Qual profissão praticamente desapareceu por causa dos elevadores automáticos?",a:["Pintor de paredes","Porteiro de prédio","Ascensorista, que apertava os botões do elevador","Engenheiro civil"],c:2,e:"Antes havia uma pessoa dentro do elevador só para operá-lo. Quando os botões automáticos chegaram, essa profissão quase acabou."},
{n:"m",t:"Tecnologia e trabalho",q:"O datilógrafo, que escrevia textos na máquina de escrever, praticamente desapareceu por causa:",a:["Do computador e da impressora","Do telefone celular","Do ônibus elétrico","Da geladeira"],c:0,e:"No computador dá para escrever, corrigir e imprimir quantas vezes quiser. A máquina de escrever ficou no passado, e a profissão também."},
{n:"m",t:"Tecnologia e trabalho",q:"Qual destas é uma profissão NOVA, que surgiu com o desenvolvimento tecnológico?",a:["Sapateiro","Desenvolvedor de aplicativos de celular","Padeiro","Pescador"],c:1,e:"Aplicativos só existem há poucas décadas, então quem os cria tem uma profissão nova. Sapateiro e padeiro existem há séculos."},
{n:"m",t:"Tecnologia e trabalho",q:"Com os caixas eletrônicos e os aplicativos de banco, o número de caixas humanos nas agências:",a:["Aumentou muito","Ficou exatamente igual","Diminuiu","Dobrou todos os anos"],c:2,e:"Quando a máquina e o celular passaram a fazer saques e pagamentos, precisou-se de menos caixas nas agências."},
{n:"m",t:"Tecnologia e trabalho",q:"Numa fábrica de carros, robôs passaram a soldar as peças. O resultado mais comum é:",a:["Ninguém mais precisa trabalhar na fábrica","A fábrica passa a produzir muito menos carros","A produção fica mais rápida e precisa, com menos operários na linha de montagem","Os carros ficam com mais defeitos"],c:2,e:"O robô solda rápido e sempre igual, então sobra menos trabalho repetitivo para as pessoas. Em troca, a fábrica precisa de quem saiba programar e consertar os robôs."},
{n:"m",t:"Tecnologia e trabalho",q:"Uma colheitadeira faz em um dia o que muitos trabalhadores levavam semanas para fazer. Isso é exemplo de:",a:["Automação e mecanização no campo","Trabalho voluntário no campo","Trabalho infantil","Extrativismo mineral"],c:0,e:"Quando a máquina assume o trabalho humano, chamamos isso de automação. No campo, ela aparece em colheitadeiras, tratores e drones."},
{n:"m",t:"Tecnologia e trabalho",q:"Uma arquiteta desenha projetos no computador de casa e envia por e-mail para os clientes. Ela trabalha:",a:["Como voluntária","Em regime de trabalho remoto (home office)","No setor primário","Como aprendiz"],c:1,e:"Home office é trabalhar de casa usando internet e computador. A tecnologia permitiu que muitos trabalhos saíssem do escritório."},
{n:"m",t:"Tecnologia e trabalho",q:"Para conseguir os empregos que surgem com a tecnologia, a pessoa precisa principalmente:",a:["Comprar um carro novo","Trabalhar mais horas por dia","Estudar e se qualificar, fazendo cursos","Mudar de cidade obrigatoriamente"],c:2,e:"As novas vagas pedem conhecimento para operar, programar e consertar máquinas. Estudo é a chave que abre essas portas. 📚"},
{n:"m",t:"Tecnologia e trabalho",q:"Antigamente, a telefonista conectava as ligações à mão numa central. Hoje:",a:["As ligações passaram a ser feitas por cartas","Ninguém mais faz ligações","Cada casa tem uma telefonista","As ligações são feitas automaticamente pelos aparelhos e sistemas"],c:3,e:"A central automática substituiu o trabalho da telefonista. É um exemplo de profissão que quase desapareceu com a tecnologia."},
{n:"m",t:"Tecnologia e trabalho",q:"A tecnologia mudou muita coisa no mundo do trabalho. Qual destas frases NÃO é verdadeira?",a:["Algumas profissões desapareceram","As pessoas não precisam mais estudar para trabalhar","Muitas tarefas ficaram mais rápidas","Novas profissões apareceram"],c:1,e:"É o contrário: com máquinas por todos os lados, estudar ficou ainda mais importante para dominar as novas ferramentas."},
{n:"m",t:"Tecnologia e trabalho",q:"Qual destas profissões surgiu por causa da internet e dos aplicativos?",a:["Ferreiro","Entregador de aplicativo de comida","Pedreiro","Agricultor"],c:1,e:"O entregador de aplicativo só existe porque há celular, internet e plataformas de pedido. Ferreiro e pedreiro são profissões antiquíssimas."},
{n:"m",t:"Setores da economia",q:"A dona de uma loja de roupas do bairro trabalha em qual setor da economia?",a:["Primário","Secundário","Extrativista","Terciário"],c:3,e:"Ela não planta nem fabrica: ela vende. Comércio é serviço, e serviço é setor terciário."},
{n:"m",t:"Setores da economia",q:"Um pescador que sai com o barco e traz peixes do mar trabalha no setor:",a:["Nenhum, pesca não é trabalho","Secundário","Terciário","Primário"],c:3,e:"Ele retira o peixe direto da natureza, e isso é setor primário. Se ele fizesse conserva de sardinha numa fábrica, seria secundário."},
{n:"m",t:"Setores da economia",q:"Uma costureira que trabalha numa fábrica de camisetas está no setor:",a:["Secundário","Primário","Terciário","Voluntário"],c:0,e:"Ela transforma o tecido em camiseta, e transformar matéria-prima é setor secundário. O tecido só existiu porque antes alguém plantou o algodão."},
{n:"m",t:"Setores da economia",q:"Um vaqueiro que cria gado numa fazenda trabalha em qual setor?",a:["Terciário","Primário","Secundário","Industrial"],c:1,e:"Criar animais é pecuária, atividade do setor primário. O frigorífico que transforma a carne em linguiça é que seria secundário."},
{n:"m",t:"Setores da economia",q:"Um operário de uma fábrica de refrigerantes trabalha no setor:",a:["Primário","Terciário","Secundário","Agropecuário"],c:2,e:"Na fábrica, água, açúcar e xarope se transformam em refrigerante. Transformação em indústria é sempre setor secundário."},
{n:"m",t:"Setores da economia",q:"Uma médica que atende pacientes num hospital trabalha no setor:",a:["Primário","Secundário","Extrativo","Terciário"],c:3,e:"Saúde é um serviço prestado às pessoas, então entra no setor terciário. Ela não retira nada da natureza nem fabrica produtos."},
{n:"m",t:"Setores da economia",q:"Um trabalhador que extrai minério de ferro de uma mina está no setor:",a:["Primário","Secundário","Terciário","Comercial"],c:0,e:"Retirar minério da natureza é extrativismo mineral, do setor primário. Já a siderúrgica que transforma esse minério em aço é secundária."},
{n:"m",t:"Setores da economia",q:"Um pedreiro que trabalha na construção de um prédio está no setor:",a:["Primário","Rural","Terciário","Secundário"],c:3,e:"A construção civil transforma cimento, areia e tijolo em prédios, então é setor secundário. É a indústria da construção."},
{n:"m",t:"Setores da economia",q:"Um guia que acompanha turistas numa cidade histórica trabalha no setor:",a:["Primário","Terciário","Secundário","Extrativista"],c:1,e:"Turismo é serviço, e serviços formam o setor terciário. Ele não produz objetos: ele atende e orienta pessoas."},
{n:"m",t:"Setores da economia",q:"Um seringueiro que extrai o látex das seringueiras na floresta trabalha no setor:",a:["Terciário","Secundário","Primário","Industrial"],c:2,e:"Tirar látex das árvores é extrativismo vegetal, atividade do setor primário. Depois, a fábrica de borracha (secundário) transforma esse látex."},
{n:"m",t:"Setores da economia",q:"Uma fábrica de móveis usa madeira para fazer armários. A madeira retirada da floresta veio de qual setor?",a:["Primário","Secundário","Terciário","Nenhum setor"],c:0,e:"Toda matéria-prima vem do setor primário, que retira da natureza. A fábrica (secundário) só entra depois, para transformar."},
{n:"m",t:"Setores da economia",q:"Um caixa de supermercado e um motorista de táxi trabalham, os dois, no setor:",a:["Primário","Secundário","Setores diferentes um do outro","Terciário"],c:3,e:"Comércio e transporte são serviços, e os dois moram no setor terciário. É o setor que mais emprega gente no Brasil."},
{n:"m",t:"Energia",q:"Numa usina hidrelétrica, o que faz as turbinas girarem para gerar eletricidade?",a:["O vento forte","A luz do sol","A força da água que desce da represa","A queima de carvão"],c:2,e:"A água guardada na represa cai com muita força e empurra as turbinas. Hidro quer dizer água, e é daí que vem o nome."},
{n:"m",t:"Energia",q:"Um parque com dezenas de aerogeradores girando no litoral gera energia:",a:["Solar","Eólica","Hidrelétrica","Nuclear"],c:1,e:"Aerogeradores usam o vento, e energia do vento é eólica. Por isso eles ficam onde o vento é forte e constante."},
{n:"m",t:"Energia",q:"Uma cidade quer gerar eletricidade poluindo o mínimo possível. Qual fonte é a melhor escolha?",a:["Termelétrica a carvão","Termelétrica a óleo diesel","Solar, com painéis nos telhados","Queima de lixo plástico"],c:2,e:"O painel solar não queima nada: ele só aproveita a luz do sol. Já as termelétricas soltam fumaça e poluem o ar. ☀️"},
{n:"m",t:"Energia",q:"Qual destas usinas polui mais o ar ao gerar eletricidade?",a:["Termelétrica a carvão","Solar","Hidrelétrica","Eólica"],c:0,e:"A termelétrica queima combustível para produzir vapor, e essa queima solta gases poluentes. As outras três não queimam nada."},
{n:"m",t:"Energia",q:"O etanol produzido a partir da cana-de-açúcar é um exemplo de energia de:",a:["Biomassa","Petróleo","Carvão mineral","Energia eólica"],c:0,e:"Biomassa é energia que vem de material de origem vegetal ou animal, como a cana. O bagaço da cana também vira energia nas usinas."},
{n:"m",t:"Energia",q:"Por que a hidrelétrica é a principal fonte de eletricidade do Brasil?",a:["Porque o Brasil quase não tem rios","Porque o Brasil tem muitos rios grandes e caudalosos","Porque no Brasil não chove","Porque é a fonte que mais polui"],c:1,e:"O Brasil é cheio de rios volumosos, perfeitos para represas e turbinas. Foi por isso que o país investiu tanto em hidrelétricas."},
{n:"m",t:"Energia",q:"Uma fábrica não consegue funcionar sem energia elétrica porque:",a:["Os funcionários não gostam do escuro","As máquinas precisam de eletricidade para se mover e produzir","A energia serve apenas para a iluminação","A eletricidade é usada só nos computadores"],c:1,e:"Esteiras, prensas, fornos e robôs só funcionam com eletricidade. Sem energia, a linha de produção simplesmente para."},
{n:"m",t:"Energia",q:"Quando falta energia elétrica numa cidade grande, o que costuma acontecer?",a:["Semáforos, hospitais, comércio e fábricas ficam prejudicados","Nada muda no dia a dia","Apenas as luzes de casa se apagam","A internet fica mais rápida"],c:0,e:"A eletricidade é o coração da cidade: sem ela param os semáforos, os elevadores e até equipamentos de hospital. Por isso a energia é tão estratégica."},
{n:"m",t:"Energia",q:"Um painel solar instalado no telhado transforma:",a:["A luz do sol em eletricidade","A força do vento em eletricidade","A água da chuva em eletricidade","O calor da fogueira em eletricidade"],c:0,e:"As placas solares captam a luz do sol e a convertem em energia elétrica. É uma fonte renovável e silenciosa."},
{n:"m",t:"Energia",q:"Uma família quer diminuir a conta de luz. Qual conjunto de atitudes ajuda mais?",a:["Trocar lâmpadas por LED e desligar aparelhos que ficam ligados sem uso","Deixar o chuveiro elétrico ligado por mais tempo","Manter a porta da geladeira aberta para gelar o ambiente","Ligar todas as televisões da casa ao mesmo tempo"],c:0,e:"Lâmpadas de LED gastam bem menos, e aparelhos em espera consomem energia silenciosamente. Pequenas mudanças diminuem a conta e ajudam o planeta."},
{n:"m",t:"Energia",q:"Qual par de fontes está classificado corretamente?",a:["Sol: não renovável / Petróleo: renovável","Sol: renovável / Petróleo: não renovável","Vento: não renovável / Carvão: renovável","Água dos rios: não renovável / Gás natural: renovável"],c:1,e:"O sol e o vento não acabam com o uso, então são renováveis. Petróleo, carvão e gás se formaram em milhões de anos e podem acabar."},
{n:"m",t:"Energia",q:"Muitos parques eólicos foram instalados no litoral do Nordeste brasileiro. O principal motivo é:",a:["Porque lá não há rios nem mar","Lá quase não existe vento","Porque a região não tem sol","Lá o vento é forte e sopra de forma constante"],c:3,e:"Para gerar energia eólica é preciso vento firme, e o litoral nordestino tem isso quase todos os dias do ano."},
{n:"d",t:"Trabalho no Brasil",q:"Qual é a diferença principal entre trabalho voluntário e trabalho informal?",a:["No voluntário a pessoa recebe mais; no informal recebe menos","Os dois são iguais, pois nenhum tem carteira assinada","No voluntário não existe pagamento; no informal existe pagamento, mas sem carteira e sem garantias","O voluntário é proibido e o informal é permitido"],c:2,e:"Cuidado com a pegadinha: os dois ficam fora da carteira assinada, mas só o informal envolve dinheiro. Voluntário trabalha de graça, por escolha."},
{n:"d",t:"Trabalho no Brasil",q:"Você compra um celular novo e, meses depois, leva para um técnico consertar a tela. Nessas duas situações:",a:["Os dois produziram serviços","Os dois produziram bens","A fábrica prestou um serviço e o técnico produziu um bem","A fábrica produziu um bem e o técnico prestou um serviço"],c:3,e:"Quem fabrica o aparelho produz um bem, algo que se pega. Quem arruma o que já existe presta um serviço."},
{n:"d",t:"Trabalho no Brasil",q:"Para o caderno chegar até a sua mochila, foi necessário o trabalho de muitas pessoas. Isso mostra que:",a:["O trabalho não influencia os produtos que usamos","O caderno é feito por uma única pessoa","Só o vendedor da papelaria trabalhou","Um produto simples depende de uma cadeia de vários trabalhos"],c:3,e:"Alguém plantou e cortou a árvore, alguém fez o papel na fábrica, alguém transportou e alguém vendeu. Cada objeto guarda o trabalho de muita gente!"},
{n:"d",t:"Trabalho no Brasil",q:"Por que se diz que o trabalho humano transforma a natureza?",a:["Porque as pessoas retiram matéria-prima da natureza e a transformam em produtos","Porque o trabalho faz chover mais","Porque a natureza se transforma sozinha, sem o trabalho","Porque as pessoas só observam a natureza"],c:0,e:"O barro vira tijolo, a árvore vira móvel, o algodão vira camiseta. O trabalho é justamente essa transformação do que a natureza oferece."},
{n:"d",t:"Trabalho no Brasil",q:"Uma babá recebe salário para cuidar de crianças; a avó cuida do neto de graça. Sobre esses dois trabalhos:",a:["Só o da babá é trabalho, porque tem pagamento","Nenhum dos dois é trabalho","Só o da avó é trabalho, porque é feito com amor","Os dois são trabalho, mas apenas o da babá é remunerado"],c:3,e:"A tarefa é a mesma e exige o mesmo esforço, então os dois são trabalho. A diferença está apenas no pagamento."},
{n:"d",t:"Trabalho no Brasil",q:"Por que a lei garante férias ao trabalhador formal?",a:["Para o trabalhador descansar e recuperar a saúde, voltando melhor ao trabalho","Para a empresa economizar salário","Porque o trabalhador não gosta do emprego","Para o trabalhador procurar outro emprego"],c:0,e:"Ninguém rende bem trabalhando sem parar o ano inteiro. As férias existem para proteger a saúde e o bem-estar de quem trabalha."},
{n:"d",t:"Trabalho no Brasil",q:"Qual destas situações mostra claramente desrespeito aos direitos do trabalhador?",a:["Trabalhar 14 horas por dia, sem descanso e sem receber hora extra","Tirar férias uma vez por ano","Receber o salário na data combinada","Ter a carteira de trabalho assinada no primeiro dia"],c:0,e:"Jornada exagerada, sem descanso e sem pagamento extra viola a lei trabalhista. As outras três situações são exemplos de direitos sendo cumpridos."},
{n:"d",t:"Trabalho no Brasil",q:"Uma cooperativa de catadores separa e vende materiais recicláveis. O trabalho deles é importante porque:",a:["Aumenta a quantidade de lixo nas ruas","Devolve o material para a indústria como matéria-prima e gera renda para as famílias","Substitui o trabalho das escolas","Impede que as fábricas funcionem"],c:1,e:"A garrafa que eles separam volta para a fábrica e vira produto novo. É trabalho que cuida do ambiente e sustenta famílias. ♻️"},
{n:"d",t:"Trabalho no Brasil",q:"Todo trabalho remunerado é automaticamente trabalho formal?",a:["Sim, quem recebe dinheiro sempre tem carteira assinada","Sim, porque a lei obriga o registro em todos os casos","Não, existe muito trabalho remunerado sem registro, que é o informal","Não, porque trabalho remunerado nunca tem registro"],c:2,e:"Aqui está a pegadinha: receber dinheiro não é o mesmo que ter direitos. O ambulante recebe, mas o trabalho dele é informal."},
{n:"d",t:"Trabalho no Brasil",q:"No dia a dia, o que significa valorizar o trabalho de alguém?",a:["Pedir sempre desconto no serviço","Reconhecer o esforço, pagar um preço justo e respeitar os direitos de quem trabalha","Achar que qualquer trabalho é fácil","Pagar depois, quando der"],c:1,e:"Valorizar é tratar bem e pagar de forma justa, seja o entregador, a diarista ou o professor. Todo trabalho merece respeito."},
{n:"d",t:"Trabalho no Brasil",q:"Se os trabalhadores de uma cidade parassem por uma semana, o efeito mais direto seria:",a:["A cidade continuaria igual","Faltariam produtos nas lojas e serviços como transporte, saúde e limpeza","Só as escolas fechariam","Os preços cairiam pela metade"],c:1,e:"Ônibus, hospital, mercado e coleta de lixo só funcionam porque alguém está trabalhando. Sem trabalho, a cidade praticamente para."},
{n:"d",t:"Trabalho no Brasil",q:"Qual afirmação sobre bens e serviços está correta?",a:["Bem e serviço são a mesma coisa com nomes diferentes","Bem é aquilo que se pode pegar e usar; serviço é o trabalho feito para atender alguém","Serviço é sempre mais caro que bem","Bem só existe no setor terciário"],c:1,e:"Um tênis é um bem; o corte de cabelo é um serviço. A diferença é simples: o bem você guarda, o serviço acontece no momento."},
{n:"d",t:"Tipos de trabalho",q:"Seu Valdir tem a própria oficina, emite nota fiscal, paga sua contribuição ao INSS e não tem patrão. Ele é:",a:["Trabalhador informal, porque não tem patrão","Voluntário da comunidade","Empregado formal da oficina","Trabalhador autônomo regularizado"],c:3,e:"Não ter patrão não significa ser informal! Ele é autônomo e, por estar regularizado e contribuir, garante direitos como a aposentadoria."},
{n:"d",t:"Tipos de trabalho",q:"Duas irmãs vendem salgados. Uma abriu MEI e contribui para o INSS; a outra não registra nada. A diferença mais importante é que:",a:["A que registrou vai vender mais salgados","A que registrou terá direito a benefícios como aposentadoria; a outra fica sem essa garantia","A que não registrou paga mais impostos","Não existe diferença nenhuma entre as duas"],c:1,e:"Contribuir hoje é garantir amparo amanhã, na aposentadoria ou numa doença. Quem fica sem registro fica sem essa rede de proteção."},
{n:"d",t:"Tipos de trabalho",q:"Qual destas situações é trabalho INFORMAL de um empregado, e não trabalho autônomo?",a:["Um jardineiro que escolhe quantos jardins vai cuidar por semana","Um pintor que atende cada semana um cliente diferente e combina o preço","Uma confeiteira que vende bolos por encomenda pela internet","Uma moça que trabalha todos os dias no mesmo mercado, com horário e chefe, mas sem carteira assinada"],c:3,e:"Ela tem chefe e horário fixo, então é empregada e deveria ter carteira assinada: é informalidade. Os outros três trabalham por conta própria, como autônomos."},
{n:"d",t:"Tipos de trabalho",q:"Por que muitas pessoas aceitam trabalho informal, mesmo sabendo que não terão garantias?",a:["Porque preferem não ter férias","Porque o trabalho informal paga sempre mais","Porque precisam de renda imediata e não conseguiram um emprego formal","Porque a lei proíbe o trabalho formal"],c:2,e:"Quando o emprego formal não aparece, muita gente aceita o informal para colocar comida na mesa. Não é falta de vontade: é necessidade."},
{n:"d",t:"Tipos de trabalho",q:"Além de proteger o trabalhador, por que o trabalho formal é importante para o país?",a:["Porque faz os preços subirem","Porque diminui o número de escolas necessárias","Porque acaba com todas as fábricas","Porque as contribuições ajudam a pagar aposentadorias e serviços públicos"],c:3,e:"Do trabalho formal saem contribuições que sustentam a aposentadoria e serviços de saúde. É uma corrente que ajuda todo mundo."},
{n:"d",t:"Tipos de trabalho",q:"Uma bancária com carteira assinada também é voluntária num hospital nos fins de semana. Isso é possível?",a:["Não, ninguém pode ter dois tipos de trabalho","Sim, uma pessoa pode ter trabalho formal e ainda fazer trabalho voluntário","Não, porque o voluntariado é proibido para quem tem emprego","Sim, mas ela perderia o direito a férias"],c:1,e:"Os tipos de trabalho não são excludentes: dá para ter emprego formal e ainda doar tempo como voluntária. 💙"},
{n:"d",t:"Tipos de trabalho",q:"O que o trabalhador informal perde quando fica doente e não consegue trabalhar por um mês?",a:["Nada, pois recebe o salário normalmente","Fica sem renda, porque não tem salário garantido nem auxílio-doença","Recebe o dobro no mês seguinte","Ganha férias remuneradas"],c:1,e:"Sem registro não há salário garantido nem auxílio pelo INSS: parou de trabalhar, parou de entrar dinheiro. É a maior fragilidade da informalidade."},
{n:"d",t:"Tipos de trabalho",q:"Uma diarista atende uma casa diferente em cada dia da semana, combina o valor e não tem patrão fixo. Ela é:",a:["Empregada formal de cada casa","Trabalhadora autônoma","Aprendiz","Voluntária"],c:1,e:"Ela é dona da própria agenda e negocia o preço com cada cliente: isso é trabalho autônomo. A empregada doméstica com carteira e horário fixo seria formal."},
{n:"d",t:"Tipos de trabalho",q:"Contratar sem carteira assinada costuma sair mais barato para quem contrata. Por que isso é um problema?",a:["Porque as empresas quebram na hora","Porque o trabalhador ganha muito mais dinheiro assim","Porque o serviço fica pior automaticamente","Porque o trabalhador fica sem direitos e sem proteção se algo acontecer"],c:3,e:"A economia de quem contrata vira risco para quem trabalha: nada de férias, 13º ou amparo em caso de acidente. Por isso a lei exige o registro."},
{n:"d",t:"Tipos de trabalho",q:"Um motorista de aplicativo dirige o próprio carro, escolhe seus horários e não tem carteira assinada. Sobre ele:",a:["É empregado formal do aplicativo, com férias pagas","É aprendiz do aplicativo","Faz trabalho voluntário, pois usa o próprio carro","Trabalha por conta própria, sem carteira assinada nem férias remuneradas"],c:3,e:"Ele decide quando e quanto trabalha, então atua por conta própria. Isso traz liberdade, mas também nenhuma das garantias do emprego formal."},
{n:"d",t:"Tipos de trabalho",q:"Se um trabalhador formal é demitido sem justa causa, ele tem direito a:",a:["Sair sem receber nada","Receber seus direitos, como férias proporcionais e o valor guardado no FGTS","Continuar trabalhando de graça por um mês","Devolver o 13º salário à empresa"],c:1,e:"O trabalho formal protege até na saída: existem valores guardados e direitos a receber. É uma segurança que o informal não tem."},
{n:"d",t:"Tipos de trabalho",q:"Qual afirmação sobre o trabalho voluntário é verdadeira?",a:["Não é trabalho de verdade, porque não gera dinheiro","Dá direito a 13º salário","Só pode ser feito por quem está desempregado","É trabalho de verdade e produz serviços úteis para a comunidade"],c:3,e:"O voluntário produz serviço real: dá aula de reforço, cuida de animais, ajuda em campanhas. Não ter salário não tira o valor do trabalho."},
{n:"d",t:"Trabalho infantil",q:"Uma família tira o filho de 12 anos da escola para trabalhar na feira. Além de ser proibido, o maior prejuízo no futuro é:",a:["Ele vai ficar sem amigos na feira","A feira vai fechar","Ele aprenderá cedo demais a contar dinheiro","Sem estudo, ele terá muito menos chances de conseguir um bom trabalho quando adulto"],c:3,e:"O trabalho infantil dá um pouco de dinheiro hoje e tira oportunidades por toda a vida. É por isso que a escola vem primeiro. 💙"},
{n:"d",t:"Trabalho infantil",q:"Qual é a diferença entre ajudar em casa e trabalho infantil?",a:["Não existe diferença: qualquer tarefa em casa é trabalho infantil","Ajudar em tarefas leves e adequadas à idade não prejudica escola nem descanso; trabalho infantil ocupa horas para gerar renda","Ajudar em casa é proibido, trabalhar fora é permitido","A diferença é só o horário do dia"],c:1,e:"Guardar os brinquedos e ajudar a pôr a mesa é aprendizado. Trabalhar horas para sustentar a casa é outra coisa, e a lei proíbe."},
{n:"d",t:"Trabalho infantil",q:"Um aprendiz de 15 anos deve cumprir quais condições, segundo a lei?",a:["Trabalhar em qualquer horário, inclusive de madrugada","Abandonar a escola durante o contrato","Continuar estudando, com jornada reduzida e sem tarefas perigosas","Trabalhar sem receber nada"],c:2,e:"O contrato de aprendiz existe para ensinar uma profissão sem tirar o jovem da escola. Por isso a jornada é curta e o risco é proibido."},
{n:"d",t:"Trabalho infantil",q:"Antigamente o trabalho de crianças era comum no Brasil. Por que ele passou a ser proibido?",a:["Porque a sociedade entendeu que a criança precisa estudar, brincar e crescer com saúde","Porque as crianças trabalhavam mal","Porque as fábricas fecharam todas","Porque faltavam adultos disponíveis"],c:0,e:"Com o tempo se compreendeu que infância não se recupera e que estudar transforma o futuro. Daí vieram leis como o ECA."},
{n:"d",t:"Trabalho infantil",q:"Alguém diz que está 'ajudando' ao dar trabalho a uma criança de 11 anos. Por que esse argumento não se sustenta?",a:["Porque ajudar de verdade é garantir escola e proteção; trabalhar prejudica a saúde e os estudos, e é ilegal","Porque a criança poderia ganhar mais em outro lugar","Porque a criança já sabe trabalhar sozinha","Porque só quem tem 10 anos pode trabalhar"],c:0,e:"Boa intenção não muda o efeito: a criança perde aula, descanso e infância. A ajuda que funciona é apoiar a família e manter a criança estudando."},
{n:"d",t:"Trabalho infantil",q:"Por que o trabalho infantil e o abandono da escola costumam andar juntos?",a:["Porque a criança que trabalha chega cansada, falta às aulas e vai ficando para trás até desistir","Porque a escola expulsa quem trabalha","Porque quem trabalha aprende mais rápido","Porque as provas ficam mais fáceis"],c:0,e:"Cansaço e faltas viram notas baixas, e notas baixas viram desânimo. Assim muitos deixam a escola, o que fecha portas no futuro."},
{n:"d",t:"Trabalho infantil",q:"Segundo o ECA, de quem é o dever de proteger a criança e garantir seus direitos?",a:["Somente da mãe e do pai","Somente da escola","Da família, da sociedade e do Estado, em conjunto","Somente do Conselho Tutelar"],c:2,e:"O ECA divide essa responsabilidade: a família cuida, a sociedade fica atenta e o Estado garante escola, saúde e proteção."},
{n:"d",t:"Trabalho infantil",q:"Qual destas medidas ajuda de fato a reduzir o trabalho infantil no Brasil?",a:["Permitir trabalho aos sábados","Contratar crianças apenas meio período","Diminuir o número de escolas","Escola em tempo integral e programas de apoio de renda às famílias"],c:3,e:"Quando a criança fica mais tempo na escola e a família tem apoio, o trabalho infantil deixa de ser 'necessário'. É o combate na raiz."},
{n:"d",t:"Trabalho infantil",q:"Qual é o papel da escola quando percebe um aluno faltando muito e chegando exausto por causa de trabalho?",a:["Conversar com a família e acionar o Conselho Tutelar para proteger a criança","Reprovar o aluno imediatamente","Ignorar, porque isso é assunto da família","Pedir que o aluno trabalhe também na escola"],c:0,e:"A escola é uma das primeiras a notar o problema e tem o dever de acionar a proteção. Assim a criança volta a ter tempo de estudar."},
{n:"d",t:"Trabalho infantil",q:"Comparado a um adulto, por que o corpo da criança sofre mais com trabalho pesado?",a:["Porque o corpo dela ainda está em crescimento e se machuca com mais facilidade","Porque a criança não gosta de trabalhar","Porque a criança é mais lenta","Porque a criança não precisa dormir"],c:0,e:"Ossos, músculos e órgãos ainda estão se formando, então peso e esforço demais causam danos duradouros. Por isso a proteção é tão importante."},
{n:"d",t:"Trabalho infantil",q:"Qual afirmação sobre o adolescente aprendiz de 15 anos está correta?",a:["Ele pode deixar a escola porque já está aprendendo uma profissão","Ele pode trabalhar à noite, se quiser","Ele pode trabalhar aprendendo uma profissão, mas sem deixar de estudar","Ele não tem direito a nenhum pagamento"],c:2,e:"Aprendiz e estudante ao mesmo tempo: é assim que a lei permite. O estudo continua sendo prioridade absoluta."},
{n:"d",t:"Tecnologia e trabalho",q:"Um banco instala caixas eletrônicos e lança um aplicativo. Qual é o efeito mais completo sobre o trabalho?",a:["Todos os funcionários do banco perdem o emprego","Diminuem as vagas de caixa nas agências, mas surgem vagas em tecnologia e segurança da informação","Nada muda no trabalho do banco","Passam a ser necessários mais caixas humanos"],c:1,e:"A tecnologia não apaga o trabalho: ela o desloca. Menos gente no balcão, mais gente cuidando de sistemas e dados."},
{n:"d",t:"Tecnologia e trabalho",q:"Uma fazenda compra uma colheitadeira moderna. O que tende a acontecer com o trabalho ali?",a:["A colheita fica mais lenta e exige mais gente","A fazenda deixa de produzir","A colheita fica rápida com menos trabalhadores, e passa a exigir operador e mecânico qualificados","Nada muda, pois a máquina não colhe sozinha"],c:2,e:"A máquina substitui muitas mãos, mas cria vagas novas para quem sabe operá-la e consertá-la. Por isso qualificação virou tão importante no campo."},
{n:"d",t:"Tecnologia e trabalho",q:"Por que estudar ficou ainda mais importante numa época de máquinas e robôs?",a:["Porque as máquinas não funcionam se ninguém estudar geografia","Porque os empregos que restam e os que surgem exigem conhecimento para operar, consertar e programar as máquinas","Porque as escolas vão substituir as fábricas","Porque estudar diminui o número de máquinas"],c:1,e:"As tarefas repetitivas vão para as máquinas, e sobra para as pessoas o trabalho que exige pensar. Estudo é o que dá acesso a esse tipo de vaga. 📚"},
{n:"d",t:"Tecnologia e trabalho",q:"A tecnologia acaba com o trabalho humano?",a:["Não; ela muda o tipo de trabalho: algumas profissões desaparecem e outras surgem","Sim, em poucos anos não haverá mais trabalho para ninguém","Sim, porque robôs fazem tudo melhor","Não, porque a tecnologia não interfere no trabalho"],c:0,e:"É uma troca constante: o datilógrafo saiu de cena, o programador entrou. O trabalho não acaba, ele se transforma."},
{n:"d",t:"Tecnologia e trabalho",q:"Quais são, ao mesmo tempo, uma vantagem e um desafio do trabalho remoto?",a:["Vantagem: economizar tempo de transporte / Desafio: precisar de boa internet e disciplina","Vantagem: não precisar trabalhar / Desafio: acordar cedo","Vantagem: receber dois salários / Desafio: usar computador","Vantagem: nunca ter reuniões / Desafio: comprar um carro"],c:0,e:"Trabalhar de casa poupa horas de trânsito, mas exige internet estável e organização para não se distrair. Toda mudança traz os dois lados."},
{n:"d",t:"Tecnologia e trabalho",q:"Uma loja passou a vender também pela internet. Quais trabalhos essa mudança tende a criar?",a:["Entregadores, gente de logística e de manutenção do site","Nenhum trabalho novo","Apenas trabalho de vitrinista","Somente trabalho voluntário"],c:0,e:"A venda online precisa de quem organize o estoque, cuide do site e leve o produto até a casa do cliente. Um novo canal cria uma nova cadeia de trabalho."},
{n:"d",t:"Tecnologia e trabalho",q:"Uma padaria compra uma máquina que amassa e assa o pão quase sozinha. O que acontece com o padeiro?",a:["Ele se torna inútil e a padaria fecha","Ele passa a trabalhar no setor primário","O trabalho dele muda: passa a programar, operar e cuidar da máquina","Ele perde o direito à carteira assinada"],c:2,e:"A máquina não decide receita, ponto de fermentação nem qualidade: alguém precisa comandá-la. O trabalho muda de mãos para cabeça."},
{n:"d",t:"Tecnologia e trabalho",q:"Qual profissão praticamente desapareceu com a chegada das câmeras digitais e dos celulares?",a:["Fotógrafo de casamento","Jornalista","Quem revelava fotos em laboratório de filme","Designer gráfico"],c:2,e:"Antes cada foto precisava ser revelada em laboratório escuro. Com a foto digital, essa etapa deixou de existir, e a profissão quase acabou."},
{n:"d",t:"Tecnologia e trabalho",q:"Num porto moderno, os guindastes são controlados por computador. O que isso exige dos trabalhadores?",a:["Qualificação e cursos técnicos para operar os sistemas","Nada de diferente do trabalho antigo","Mais força física do que antes","Que trabalhem sem descanso"],c:0,e:"Operar por computador exige treinamento e conhecimento técnico. A força física dá lugar ao conhecimento especializado."},
{n:"d",t:"Tecnologia e trabalho",q:"Uma fábrica automatizada produz muito mais com menos funcionários. Para o país, o principal desafio é:",a:["Fechar as fábricas automatizadas","Aumentar o trabalho infantil","Proibir o uso de computadores","Qualificar as pessoas para os novos tipos de emprego que aparecem"],c:3,e:"Se a máquina assume a tarefa antiga, é preciso preparar as pessoas para as tarefas novas. Educação e cursos são a resposta."},
{n:"d",t:"Tecnologia e trabalho",q:"Existem aplicativos que traduzem textos automaticamente. Por que os tradutores continuam sendo necessários?",a:["Porque os aplicativos só funcionam à noite","Porque ninguém usa aplicativos de tradução","Porque textos difíceis, piadas e documentos exigem revisão e entendimento humano","Porque tradutores traduzem mais rápido que qualquer aplicativo"],c:2,e:"A máquina erra o sentido, o tom e as expressões da língua. O profissional continua necessário para revisar e dar sentido ao texto."},
{n:"d",t:"Setores da economia",q:"O leite sai da fazenda, vira queijo na fábrica e é vendido no mercado. Nessa ordem, os setores são:",a:["Secundário, primário e terciário","Primário, secundário e terciário","Terciário, secundário e primário","Primário, terciário e secundário"],c:1,e:"Tirar o leite da vaca é primário, transformar em queijo é secundário e vender é terciário. Essa sequência é uma cadeia produtiva."},
{n:"d",t:"Setores da economia",q:"Na cadeia algodão plantado → tecelagem → loja de roupas, qual etapa pertence ao setor secundário?",a:["O plantio do algodão na lavoura","A tecelagem, que transforma o algodão em tecido","A venda da roupa na loja","O transporte até o shopping"],c:1,e:"Secundário é sempre a etapa que transforma. O algodão vira fio, o fio vira tecido e o tecido vira camiseta, tudo dentro da indústria."},
{n:"d",t:"Setores da economia",q:"Seu Zé planta mandioca e também tem uma casa de farinha onde transforma a mandioca em farinha. As atividades dele estão:",a:["No primário (plantar) e no secundário (transformar em farinha)","Só no setor secundário, porque ele faz farinha","Só no setor primário, porque ele é agricultor","No setor terciário, porque ele vende"],c:0,e:"Cuidado com a pegadinha: a mesma pessoa pode atuar em dois setores. Plantar é primário; transformar a mandioca em farinha é secundário."},
{n:"d",t:"Setores da economia",q:"Dona Ana colhe frutas no quintal, faz doces com elas e vende na feira. A etapa de FAZER o doce pertence ao setor:",a:["Secundário","Primário","Terciário","Nenhum, é trabalho doméstico"],c:0,e:"Colher a fruta é primário e vender na feira é terciário, mas transformar fruta em doce é secundário. Ela passa pelos três setores!"},
{n:"d",t:"Setores da economia",q:"Pensando no suco de laranja da caixinha, qual atividade pertence ao setor primário?",a:["A venda no supermercado","A produção do suco na indústria","O cultivo e a colheita da laranja no pomar","A propaganda na televisão"],c:2,e:"Tudo começa na terra: sem a laranja colhida não existe suco. Essa primeira etapa, retirada da natureza, é o setor primário."},
{n:"d",t:"Setores da economia",q:"Por que o setor terciário é o que mais emprega no Brasil hoje?",a:["Porque não existem mais fábricas no país","Porque serviços não precisam de trabalhadores","Porque a agricultura brasileira acabou","Porque a maioria da população vive em cidades, que precisam de muitos serviços"],c:3,e:"Cidade grande significa muitos mercados, ônibus, escolas, hospitais e bancos. Todos esses serviços exigem muita gente trabalhando."},
{n:"d",t:"Setores da economia",q:"Uma fábrica de móveis parou de produzir porque faltou madeira. Isso mostra que:",a:["O setor secundário depende do primário para receber matéria-prima","O setor primário depende das lojas para existir","Os setores não têm nenhuma ligação entre si","Fábricas não usam matéria-prima"],c:0,e:"A indústria só transforma o que o setor primário fornece. Se a matéria-prima falta, a produção para: os setores são elos de uma mesma corrente."},
{n:"d",t:"Setores da economia",q:"Um caminhoneiro leva tomates da roça até a fábrica de molho. O trabalho dele pertence ao setor:",a:["Terciário, porque transporte é um serviço","Secundário, porque entrega para a fábrica","Primário, porque carrega produto agrícola","A nenhum setor, pois ele está só dirigindo"],c:0,e:"Ele não plantou o tomate nem fez o molho: ele prestou o serviço de transporte. Todo transporte é setor terciário."},
{n:"d",t:"Setores da economia",q:"O que acontece com o valor de um produto conforme ele passa pelos setores da economia?",a:["Ele diminui em cada etapa","O valor fica sempre igual","Cada etapa acrescenta valor, então o produto final custa mais que a matéria-prima","Só a última etapa tem valor"],c:2,e:"O trigo é baratinho, a farinha custa mais e o pão na padaria custa mais ainda. Cada trabalho realizado acrescenta valor ao produto."},
{n:"d",t:"Setores da economia",q:"Qual sequência representa corretamente uma cadeia produtiva do primário ao terciário?",a:["Açougue → frigorífico → boi na fazenda","Frigorífico → boi na fazenda → açougue","Boi na fazenda → frigorífico → açougue","Açougue → boi na fazenda → frigorífico"],c:2,e:"A cadeia sempre começa na natureza, passa pela indústria e termina no comércio. Criar o boi, processar a carne e vender ao consumidor."},
{n:"d",t:"Setores da economia",q:"Alguém diz: 'A pesca industrial usa navios e máquinas, então é setor secundário.' Essa afirmação está:",a:["Certa, porque usa máquinas modernas","Errada: continua sendo primário, pois retira o peixe da natureza","Certa, porque acontece longe da costa","Errada: na verdade é setor terciário"],c:1,e:"Usar máquina não muda o setor: o que importa é o que a atividade faz. Retirar da natureza é sempre primário, mesmo com navio grande."},
{n:"d",t:"Setores da economia",q:"Petróleo extraído do mar, refinaria que produz gasolina e posto que vende ao motorista pertencem, na ordem, aos setores:",a:["Primário, terciário e secundário","Secundário, terciário e primário","Terciário, primário e secundário","Primário, secundário e terciário"],c:3,e:"Extrair petróleo é retirar da natureza (primário), refinar é transformar (secundário) e vender no posto é serviço (terciário)."},
{n:"d",t:"Energia",q:"Numa seca forte, os reservatórios das hidrelétricas baixam muito. O que costuma acontecer no Brasil?",a:["A energia fica de graça","Todas as fábricas fecham para sempre","Ligam-se mais termelétricas, a conta de luz sobe e a poluição aumenta","Passa a chover automaticamente"],c:2,e:"Com menos água, o país aciona as termelétricas, que são mais caras e poluentes. É por isso que economizar energia na seca ajuda a todos."},
{n:"d",t:"Energia",q:"Por que a energia solar e a eólica são chamadas de energias limpas?",a:["Porque as usinas são pintadas de branco","Porque não queimam combustível, então quase não poluem o ar","Porque não geram nenhuma eletricidade","Porque só funcionam em cidades limpas"],c:1,e:"Sem queima não há fumaça nem gases poluentes. O sol e o vento fazem o trabalho de graça e sem sujar o ar. ☀️"},
{n:"d",t:"Energia",q:"Se a termelétrica polui mais, por que o Brasil ainda a utiliza?",a:["Porque é a fonte mais barata do mundo","Porque produz água para os rios","Porque não precisa de combustível","Porque funciona a qualquer hora, sem depender de chuva ou vento, garantindo energia quando as outras faltam"],c:3,e:"Ela é uma espécie de reserva: pode ser ligada na hora em que faltar água ou vento. A garantia de energia vem com o custo da poluição."},
{n:"d",t:"Energia",q:"Por que o petróleo é considerado uma fonte não renovável?",a:["Porque é muito caro","Porque não serve para gerar energia","Porque levou milhões de anos para se formar e pode acabar com o uso","Porque vem do vento"],c:2,e:"Ele se formou de restos de seres vivos ao longo de milhões de anos. O que a natureza não repõe no nosso tempo é não renovável."},
{n:"d",t:"Energia",q:"Painéis solares não geram eletricidade durante a noite. Como se resolve esse problema?",a:["Ligando os painéis ao contrário","Deixando os painéis descansarem por uma semana","Combinando outras fontes de energia ou guardando eletricidade em baterias","Aumentando o tamanho dos painéis"],c:2,e:"Como cada fonte tem seus limites, o segredo é combinar fontes e usar baterias. Assim há energia disponível de dia e de noite."},
{n:"d",t:"Energia",q:"Por que economizar energia elétrica ajuda o meio ambiente?",a:["Porque quanto menos energia é consumida, menos necessário é construir usinas poluentes e novas represas","Porque economizar energia faz chover","Porque a energia economizada volta para o sol","Porque diminui o número de rios do país"],c:0,e:"Toda energia consumida precisa ser produzida em algum lugar. Consumindo menos, o país precisa de menos usinas e agride menos a natureza. 🌱"},
{n:"d",t:"Energia",q:"Uma indústria instala painéis solares no telhado do galpão. Quais são as vantagens?",a:["Gasta menos com a conta de luz ao longo do tempo e polui menos","A fábrica passa a produzir mais poluição","As máquinas passam a funcionar sem energia","A empresa deixa de precisar de trabalhadores"],c:0,e:"O investimento inicial se paga com a economia na conta de luz, e a energia usada é limpa. Bom para a empresa e para o planeta."},
{n:"d",t:"Energia",q:"Por que a energia de biomassa produzida a partir da cana-de-açúcar é considerada renovável?",a:["Porque a cana existe em quantidade infinita no subsolo","Porque a cana não é um ser vivo","Porque a cana não precisa de água nem de sol","Porque a cana pode ser plantada novamente a cada safra"],c:3,e:"Diferente do petróleo, a cana se replanta e cresce em poucos meses. Fonte que se repõe rapidamente é fonte renovável."},
{n:"d",t:"Energia",q:"A construção de uma grande hidrelétrica também traz impactos. Qual deles é real?",a:["O rio passa a correr para trás","A região perde toda a energia elétrica","A água da represa deixa de existir","Grandes áreas são alagadas, o rio muda e moradores e animais precisam se deslocar"],c:3,e:"Represar um rio inunda florestas e até vilas inteiras. Mesmo sendo uma fonte limpa, a hidrelétrica muda muito a paisagem e a vida local."},
{n:"d",t:"Energia",q:"Ônibus, caminhões e carros no Brasil funcionam principalmente com qual tipo de energia?",a:["Energia eólica captada no teto","Apenas energia solar","Combustíveis como diesel, gasolina e etanol, e alguns veículos com eletricidade","Somente energia hidrelétrica"],c:2,e:"Quase todo o transporte queima combustível no motor, e por isso o petróleo ainda é tão importante. Os veículos elétricos vêm crescendo aos poucos."},
{n:"d",t:"Energia",q:"Uma cidade quer garantir energia durante todo o ano, com chuva ou sem chuva. Qual é a melhor estratégia?",a:["Depender apenas da hidrelétrica","Desligar a energia nos meses de seca","Usar somente painéis solares","Combinar várias fontes, como hidrelétrica, solar e eólica, pois cada uma tem seus limites"],c:3,e:"Se só houver uma fonte, qualquer problema deixa a cidade no escuro. Misturar fontes é como ter mais de um caminho para chegar em casa."},
{n:"d",t:"Energia",q:"Qual afirmação relaciona corretamente energia e indústria?",a:["A indústria não usa energia, apenas as casas usam","A indústria produz sua própria eletricidade sem nenhuma fonte","Sem energia elétrica as máquinas param, então a produção industrial depende diretamente da oferta de energia","Falta de energia aumenta a produção das fábricas"],c:2,e:"Energia é o combustível da indústria: sem ela, esteiras, fornos e robôs ficam paralisados. Por isso o país planeja usinas junto ao crescimento industrial."},
];
